fn submit(r: &mut Runtime, a: bool, b: bool, c: bool, d: f64) {
    r.set_input("start", Value::Bool(a)).unwrap();
    r.set_input("stop", Value::Bool(b)).unwrap();
    r.set_input("low_water", Value::Bool(c)).unwrap();
    r.set_input("moisture", Value::Number(d)).unwrap();
}

fn frame(scan_id: u64, time: u64) -> ScanFrameV1 {
    ScanFrameV1 {
        scan_id,
        logical_time_ms: time,
        inputs: vec![
            ScanInput {
                name: "start".into(),
                value: Value::Bool(true),
            },
            ScanInput {
                name: "stop".into(),
                value: Value::Bool(false),
            },
            ScanInput {
                name: "low_water".into(),
                value: Value::Bool(false),
            },
            ScanInput {
                name: "moisture".into(),
                value: Value::Number(90.0),
            },
        ],
    }
}
